    "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>LeapOS-Gateway</title>\n  <style>\n/* LeapOS-Gateway Web UI - layout/styling aligned with CDG2026 BurnerGateway console */\n:root {\n\t--bg: #f5f7f9;\n\t--bg-2: #e9eef2;\n\t--panel: #ffffff;\n\t--panel-2: #f3f6f8;\n\t--text: #1c1f23;\n\t--muted: #5c6a76;\n\t--accent: #cc0000;\n\t--accent-2: #003b5c;\n\t--stroke: #d8e0e6;\n}\n\n* {\n\tbox-sizing: border-box;\n}\n\nbody {\n\tmargin: 0;\n\tmin-height: 100vh;\n\tbackground: linear-gradient(180deg, var(--bg), var(--bg-2));\n\tcolor: var(--text);\n\tfont-family: \"Trebuchet MS\", \"Gill Sans MT\", \"Tahoma\", sans-serif;\n\tletter-spacing: 0.15px;\n}\n\n.app {\n\tmax-width: 980px;\n\tmargin: 0 auto 56px;\n\tpadding: 24px;\n}\n\n.header-card {\n\tbackground: linear-gradient(180deg, var(--panel), var(--panel-2));\n\tborder: 1px solid var(--stroke);\n\tborder-radius: 10px;\n\tpadding: 20px 24px;\n\tmargin-bottom: 16px;\n}\n\n.brand {\n\tdisplay: flex;\n\talign-items: center;\n\tjustify-content: space-between;\n\tgap: 16px;\n}\n\n.brand-mark {\n\twidth: 72px;\n\theight: 72px;\n\tborder-radius: 10px;\n\tborder: 1px solid var(--stroke);\n\tbackground: linear-gradient(145deg, var(--accent-2), #005f8f);\n\tcolor: #fff;\n\tdisplay: flex;\n\talign-items: center;\n\tjustify-content: center;\n\tfont-weight: 700;\n\tfont-size: 13px;\n\tletter-spacing: 0.8px;\n\tflex-shrink: 0;\n}\n\nh1 {\n\tmargin: 0;\n\tfont-family: Georgia, \"Times New Roman\", serif;\n\tfont-size: 42px;\n\tfont-weight: 700;\n\tletter-spacing: 0.4px;\n}\n\n.subtitle {\n\tcolor: var(--muted);\n\tfont-size: 14px;\n\tfont-weight: 600;\n\ttext-transform: uppercase;\n\tletter-spacing: 1.2px;\n\tmargin: 8px 0 0;\n}\n\n.lead {\n\tcolor: var(--muted);\n\tmargin: 10px 0 0;\n\tline-height: 1.5;\n}\n\n.header-card .nav-bar {\n\tdisplay: flex;\n\tflex-direction: row;\n\tflex-wrap: wrap;\n\tgap: 8px;\n\talign-items: center;\n\tjustify-content: flex-end;\n\tpadding: 12px 0 0;\n\tmargin-top: 16px;\n\tborder-top: 1px solid var(--stroke);\n}\n\n.card {\n\tbackground: linear-gradient(180deg, var(--panel), var(--panel-2));\n\tborder: 1px solid var(--stroke);\n\tborder-radius: 10px;\n\tpadding: 20px 24px;\n\tmargin-top: 16px;\n}\n\n.card h2 {\n\tmargin: 0 0 10px;\n\tfont-size: 16px;\n\ttext-transform: uppercase;\n\tletter-spacing: 1.2px;\n\tcolor: var(--muted);\n}\n\n.status-card {\n\tpadding: 0;\n\toverflow: hidden;\n}\n\n.status-top {\n\tpadding: 18px 20px 16px;\n\tborder-bottom: 1px solid var(--stroke);\n\tbackground: linear-gradient(180deg, #fbfcfd, #f6f9fb);\n}\n\n.status-toolbar {\n\tdisplay: flex;\n\talign-items: center;\n\tjustify-content: space-between;\n\tgap: 16px;\n\tflex-wrap: wrap;\n\tmargin-top: 12px;\n}\n\n.status-indicator-row,\n.status-metrics {\n\tdisplay: flex;\n\tflex-wrap: wrap;\n\tgap: 8px;\n\talign-items: center;\n}\n\n.status-metrics {\n\talign-items: stretch;\n}\n\n.status-metric {\n\tdisplay: flex;\n\tflex-direction: column;\n\talign-items: center;\n\tjustify-content: center;\n\tmin-width: 88px;\n\tpadding: 8px 14px;\n\tborder: 1px solid var(--stroke);\n\tborder-radius: 8px;\n\tbackground: #fff;\n}\n\n.status-metric-value {\n\tfont-size: 22px;\n\tfont-weight: 700;\n\tline-height: 1;\n\tcolor: var(--text);\n}\n\n.status-metric-label {\n\tmargin-top: 4px;\n\tfont-size: 11px;\n\tcolor: var(--muted);\n\ttext-transform: uppercase;\n\tletter-spacing: 0.6px;\n}\n\n.status-pill {\n\tdisplay: inline-flex;\n\talign-items: center;\n\tgap: 8px;\n\tpadding: 7px 12px;\n\tborder: 1px solid var(--stroke);\n\tborder-radius: 999px;\n\tbackground: #fff;\n\tfont-size: 12px;\n\twhite-space: nowrap;\n}\n\n.status-pill-label {\n\tfont-size: 10px;\n\tfont-weight: 700;\n\ttext-transform: uppercase;\n\tletter-spacing: 0.7px;\n\tcolor: var(--muted);\n}\n\n.status-pill-value {\n\tfont-size: 13px;\n\tfont-weight: 700;\n\tcolor: var(--text);\n}\n\n.status-pill.good {\n\tbackground: #e8f5e9;\n\tborder-color: #a5d6a7;\n}\n\n.status-pill.good .status-pill-value {\n\tcolor: #2e7d32;\n}\n\n.status-pill.bad {\n\tbackground: #ffebee;\n\tborder-color: #ef9a9a;\n}\n\n.status-pill.bad .status-pill-value {\n\tcolor: #c62828;\n}\n\n.status-pill.warn {\n\tbackground: #fff3e0;\n\tborder-color: #ffcc80;\n}\n\n.status-pill.warn .status-pill-value {\n\tcolor: #e65100;\n}\n\n.status-card-footer,\n.card-toolbar {\n\tdisplay: flex;\n\tflex-wrap: wrap;\n\talign-items: center;\n\tgap: 8px;\n\tpadding-top: 4px;\n}\n\n.panel-grid {\n\tdisplay: grid;\n\tgrid-template-columns: 1fr 1fr;\n\tgap: 16px;\n\tmargin-top: 0;\n}\n\n.row {\n\tdisplay: grid;\n\tgrid-template-columns: 150px 1fr;\n\tgap: 10px;\n\talign-items: center;\n\tmargin-bottom: 8px;\n}\n\nlabel {\n\tfont-size: 12px;\n\tcolor: var(--muted);\n}\n\ninput,\nselect {\n\tpadding: 8px 10px;\n\tborder-radius: 4px;\n\tborder: 1px solid var(--stroke);\n\tbackground: #fff;\n\tcolor: var(--text);\n\toutline: none;\n\twidth: 100%;\n\tfont: inherit;\n}\n\ninput[type=\"checkbox\"] {\n\twidth: auto;\n\tmargin-right: 6px;\n}\n\n.editor-grid {\n\tdisplay: grid;\n\tgrid-template-columns: 1fr 1fr;\n\tgap: 12px;\n}\n\n.editor-grid .full {\n\tgrid-column: 1 / -1;\n}\n\n.actions {\n\tmargin-top: 12px;\n}\n\n.button {\n\tdisplay: inline-block;\n\tpadding: 8px 12px;\n\tborder-radius: 4px;\n\tborder: 1px solid var(--stroke);\n\tbackground: #fff;\n\tcolor: var(--text);\n\tfont-weight: 600;\n\tfont-size: 13px;\n\tcursor: pointer;\n\tmargin-right: 8px;\n\tmargin-bottom: 8px;\n\tfont-family: inherit;\n}\n\n.button.primary {\n\tborder-color: transparent;\n\tbackground: linear-gradient(180deg, #e10000, #b30000);\n\tcolor: #fff;\n}\n\n.button.small {\n\tpadding: 5px 8px;\n\tfont-size: 12px;\n\tmargin: 0 4px 0 0;\n}\n\n.hint {\n\tcolor: var(--muted);\n\tfont-size: 12px;\n\tline-height: 1.5;\n\tmargin: 8px 0 0;\n}\n\n.muted {\n\tcolor: var(--muted);\n}\n\n.message {\n\tpadding: 10px 12px;\n\tborder-radius: 4px;\n\tfont-size: 13px;\n\tmargin-top: 10px;\n\tdisplay: none;\n}\n\n.message.error {\n\tbackground: #fff5f5;\n\tborder: 1px solid #dc3545;\n\tcolor: #721c24;\n\tdisplay: block;\n}\n\n.message.success {\n\tbackground: #e7f5e7;\n\tborder: 1px solid #28a745;\n\tcolor: #155724;\n\tdisplay: block;\n}\n\n.grid {\n\twidth: 100%;\n\tborder-collapse: collapse;\n\tmargin-top: 10px;\n\tbackground: #fff;\n}\n\n.grid th,\n.grid td {\n\tborder: 1px solid var(--stroke);\n\tpadding: 8px;\n\ttext-align: left;\n\tfont-size: 12px;\n\tvertical-align: middle;\n}\n\n.grid th {\n\tbackground-color: #eef3f7;\n\tcolor: #40515f;\n\ttext-transform: uppercase;\n\tletter-spacing: 0.8px;\n}\n\n.grid tr.selected-row td {\n\tbackground: #fff8e1;\n}\n\ncode {\n\tbackground: #eef3f7;\n\tpadding: 1px 5px;\n\tborder-radius: 4px;\n\tfont-size: 12px;\n}\n\n.config-pre {\n\tbackground: #f8fafb;\n\tborder: 1px solid var(--stroke);\n\tborder-radius: 6px;\n\tpadding: 12px;\n\toverflow: auto;\n\tfont-family: Consolas, \"Courier New\", monospace;\n\tfont-size: 11px;\n\tline-height: 1.45;\n\tmax-height: 240px;\n\twhite-space: pre-wrap;\n\tword-break: break-word;\n}\n\n.bits {\n\tfont-family: Consolas, \"Courier New\", monospace;\n\tletter-spacing: 0.08em;\n\tfont-size: 11px;\n}\n\n.bit {\n\tdisplay: inline-block;\n\twidth: 1.1rem;\n\ttext-align: center;\n\tmargin-right: 0.15rem;\n\tborder-radius: 3px;\n\tbackground: #eef3f7;\n\tcolor: var(--muted);\n}\n\n.bit.on {\n\tbackground: #2e7d32;\n\tcolor: #fff;\n}\n\n.io-ok {\n\tcolor: #2e7d32;\n\tfont-weight: 700;\n}\n\n.io-bad {\n\tcolor: #c62828;\n\tfont-weight: 700;\n}\n\n.checkbox-row {\n\tdisplay: flex;\n\talign-items: center;\n\tgap: 8px;\n\tmargin-top: 8px;\n\tfont-size: 13px;\n\tcolor: var(--text);\n}\n\n.footer {\n\ttext-align: center;\n\tpadding: 24px;\n\tcolor: var(--muted);\n\tfont-size: 12px;\n\tmargin-top: 24px;\n}\n\n@media (max-width: 980px) {\n\t.panel-grid,\n\t.editor-grid {\n\t\tgrid-template-columns: 1fr;\n\t}\n\n\t.row {\n\t\tgrid-template-columns: 1fr;\n\t}\n\n\t.status-toolbar {\n\t\tflex-direction: column;\n\t\talign-items: stretch;\n\t}\n\n\t.brand {\n\t\tflex-direction: column;\n\t\talign-items: flex-start;\n\t}\n\n\th1 {\n\t\tfont-size: 32px;\n\t}\n}\n\n</style>\n</head>\n<body>\n<div class=\"app\">\n\n  <div class=\"header-card\">\n    <div class=\"brand\">\n      <div>\n        <h1>LeapOS-Gateway</h1>\n        <p class=\"subtitle\">Configuration Console</p>\n      </div>\n      <div class=\"brand-mark\">LEAP</div>\n    </div>\n    <p class=\"lead\">Discover LEAP devices, map EtherNet/IP assemblies, and manage gateway configuration.</p>\n    <div class=\"nav-bar\">\n      <button class=\"button primary\" type=\"button\" id=\"scan\">Scan LEAP</button>\n      <button class=\"button\" type=\"button\" id=\"connect_leap\">Connect LEAP</button>\n      <button class=\"button\" type=\"button\" id=\"reload\">Reload config</button>\n      <button class=\"button\" type=\"button\" id=\"status\">Refresh status</button>\n      <button class=\"button primary\" type=\"button\" id=\"save\">Apply to runtime</button>\n      <button class=\"button primary\" type=\"button\" id=\"persist\">Save to disk</button>\n    </div>\n    <div id=\"msg\" class=\"message\"></div>\n  </div>\n\n  <div class=\"card status-card\">\n    <div class=\"status-top\">\n      <h2>Status</h2>\n      <div class=\"status-toolbar\">\n        <div class=\"status-indicator-row\">\n          <span id=\"pillLeap\" class=\"status-pill bad\">\n            <span class=\"status-pill-label\">LEAP</span>\n            <span class=\"status-pill-value\">Idle</span>\n          </span>\n          <span id=\"pillComm\" class=\"status-pill bad\">\n            <span class=\"status-pill-label\">PD Comm</span>\n            <span class=\"status-pill-value\">No data</span>\n          </span>\n          <span id=\"pillStorage\" class=\"status-pill warn\">\n            <span class=\"status-pill-label\">Storage</span>\n            <span class=\"status-pill-value\">Unknown</span>\n          </span>\n        </div>\n        <div class=\"status-metrics\">\n          <div class=\"status-metric\">\n            <span class=\"status-metric-value\" id=\"metricMappings\">0</span>\n            <span class=\"status-metric-label\">Mappings</span>\n          </div>\n          <div class=\"status-metric\">\n            <span class=\"status-metric-value\" id=\"metricOpPeers\">0</span>\n            <span class=\"status-metric-label\">OP Peers</span>\n          </div>\n        </div>\n      </div>\n    </div>\n    <pre id=\"stat\" class=\"config-pre\" style=\"margin:0;border:0;border-radius:0;max-height:160px;\">Loading...</pre>\n  </div>\n\n  <div class=\"card\">\n    <h2>Network</h2>\n    <div class=\"panel-grid\">\n      <div>\n        <div class=\"row\">\n          <label for=\"ipv4\">IPv4 address</label>\n          <input id=\"ipv4\" type=\"text\" placeholder=\"192.168.1.2\">\n        </div>\n        <div class=\"row\">\n          <label for=\"mask\">Subnet mask</label>\n          <input id=\"mask\" type=\"text\" placeholder=\"255.255.255.0\">\n        </div>\n      </div>\n      <div>\n        <div class=\"row\">\n          <label for=\"cyclic_ms\">LEAP cyclic period (ms)</label>\n          <input id=\"cyclic_ms\" type=\"number\" min=\"10\" max=\"1000\" step=\"1\">\n        </div>\n        <div class=\"row\">\n          <label for=\"ifname\">Interface</label>\n          <input id=\"ifname\" type=\"text\" placeholder=\"re0\">\n        </div>\n      </div>\n    </div>\n    <p class=\"hint\">IP changes take effect after reboot. <strong>Save to disk</strong> requires boot from the CF/IDE image (<code>leapos-gateway.img</code>), not the ISO alone.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>EtherNet/IP assemblies (PLC connection)</h2>\n    <p class=\"hint\" style=\"margin-top:0\">Use these in Studio 5000 / RSLinx exclusive-owner connection:</p>\n    <ul class=\"hint\" style=\"margin:0;padding-left:1.2rem\">\n      <li>Input assembly <code>100</code> (32 bytes) - gateway -&gt; PLC</li>\n      <li>Output assembly <code>150</code> (32 bytes) - PLC -&gt; gateway</li>\n      <li>Config assembly <code>151</code> (10 bytes)</li>\n    </ul>\n  </div>\n\n  <div class=\"card\">\n    <h2>LEAP peer mappings</h2>\n    <div class=\"card-toolbar\">\n      <button class=\"button\" type=\"button\" id=\"map_add\">+ Add mapping</button>\n      <span id=\"map_edit_label\" class=\"muted\"></span>\n    </div>\n    <table class=\"grid\">\n      <thead>\n        <tr>\n          <th>MAC</th><th>Profile</th><th>In byte</th><th>Out byte</th><th>Status</th><th>Width</th><th>On</th><th>Action</th>\n        </tr>\n      </thead>\n      <tbody id=\"mapping_rows\"><tr><td colspan=\"8\" class=\"muted\">No mappings - use Map on a discovered peer</td></tr></tbody>\n    </table>\n    <div class=\"editor-grid\" style=\"margin-top:16px\">\n      <div class=\"row\">\n        <label for=\"map_mac\">Peer MAC</label>\n        <input id=\"map_mac\" type=\"text\" placeholder=\"aa:bb:cc:dd:ee:ff\">\n      </div>\n      <div class=\"row\">\n        <label for=\"map_profile\">Profile ID</label>\n        <input id=\"map_profile\" type=\"text\" placeholder=\"0x00010001\">\n      </div>\n      <div class=\"row\">\n        <label for=\"map_input_byte\">Input byte (E/IP asm 100)</label>\n        <input id=\"map_input_byte\" type=\"number\" min=\"0\" max=\"31\">\n      </div>\n      <div class=\"row\">\n        <label for=\"map_output_byte\">Output byte (E/IP asm 150)</label>\n        <input id=\"map_output_byte\" type=\"number\" min=\"0\" max=\"31\">\n      </div>\n      <div class=\"row\">\n        <label for=\"map_status_byte\">Status byte (E/IP asm 100)</label>\n        <input id=\"map_status_byte\" type=\"number\" min=\"0\" max=\"31\">\n      </div>\n      <div class=\"row\">\n        <label for=\"map_width\">Digital width (bits)</label>\n        <input id=\"map_width\" type=\"number\" min=\"1\" max=\"16\" value=\"8\">\n      </div>\n      <div class=\"full checkbox-row\">\n        <label><input id=\"map_enabled\" type=\"checkbox\"> Enable this mapping</label>\n      </div>\n    </div>\n    <p class=\"hint\">Pick a discovered peer with <strong>Map</strong> to add or update a slot (each device keeps its own E/IP byte offsets). Edit a row with <strong>Edit</strong>, then <strong>Apply</strong>. Use <strong>Connect LEAP</strong> to bootstrap ownership (DISC -&gt; MGMT -&gt; OP) on demand.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>Live I/O monitor</h2>\n    <div class=\"card-toolbar\">\n      <label class=\"checkbox-row\" style=\"margin:0\"><input id=\"io_auto\" type=\"checkbox\" checked> Auto-refresh (500 ms)</label>\n      <button class=\"button\" type=\"button\" id=\"io_refresh\">Refresh I/O</button>\n      <span id=\"io_session\" class=\"muted\"></span>\n    </div>\n    <table class=\"grid\">\n      <thead>\n        <tr>\n          <th>Peer</th><th>Comm</th>\n          <th>LEAP inputs<br><span class=\"muted\">device -&gt; gateway</span></th>\n          <th>LEAP outputs<br><span class=\"muted\">gateway -&gt; device</span></th>\n          <th>E/IP in byte<br><span class=\"muted\">asm 100 -&gt; PLC</span></th>\n          <th>E/IP out byte<br><span class=\"muted\">asm 150 &lt;- PLC</span></th>\n        </tr>\n      </thead>\n      <tbody id=\"io_rows\"><tr><td colspan=\"6\" class=\"muted\">Waiting for data...</td></tr></tbody>\n    </table>\n    <p class=\"hint\">Updates when the gateway owns the LEAP session (phase <code>OP</code>) and cyclic PD is running.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>Discovered peers</h2>\n    <table class=\"grid\">\n      <thead>\n        <tr><th>MAC</th><th>Profile</th><th>State</th><th>Owner</th><th>Action</th></tr>\n      </thead>\n      <tbody id=\"peers\"></tbody>\n    </table>\n  </div>\n\n  <div class=\"card\">\n    <h2>Raw config preview</h2>\n    <pre id=\"config_preview\" class=\"config-pre\"></pre>\n  </div>\n\n  <footer class=\"footer\">\n    LeapOS-Gateway - LEAP / EtherNet/IP Bridge | UI v5 (CDG console)\n    <br>(c) 2026 Adam G. Sweeney | Vanfab, Inc | Van Voorst Lumber Company\n  </footer>\n</div>\n<script>\nconst LEAP_STATES = {\n  '0x0000': 'BOOT', '0x0001': 'INIT', '0x0002': 'CONFIGURED',\n  '0x0003': 'SAFE', '0x0004': 'OP', '0x0005': 'FAULT'\n};\n\nconst MAX_MAPPINGS = 16;\n\nconst defaults = {\n  ipv4: '192.168.1.2',\n  mask: '255.255.255.0',\n  cyclic_ms: 50,\n  ifname: 're0'\n};\n\nconst mappingDefaults = {\n  mac: '',\n  profile: '0x00010001',\n  input_byte: 0,\n  output_byte: 2,\n  status_byte: 4,\n  width: 8,\n  enabled: false\n};\n\nlet mappings = [];\nlet selectedMappingIdx = -1;\n\nfunction $(id) { return document.getElementById(id); }\n\nfunction defaultMapping(index) {\n  return {\n    mac: mappingDefaults.mac,\n    profile: mappingDefaults.profile,\n    input_byte: index,\n    output_byte: index + 2,\n    status_byte: index + 4,\n    width: mappingDefaults.width,\n    enabled: mappingDefaults.enabled\n  };\n}\n\nfunction nextMappingBytes() {\n  if (mappings.length === 0) {\n    return { input_byte: 0, output_byte: 2, status_byte: 4 };\n  }\n  let maxIn = 0;\n  let maxOut = 0;\n  let maxStatus = 0;\n  mappings.forEach(m => {\n    maxIn = Math.max(maxIn, m.input_byte);\n    maxOut = Math.max(maxOut, m.output_byte);\n    maxStatus = Math.max(maxStatus, m.status_byte);\n  });\n  return {\n    input_byte: maxIn + 1,\n    output_byte: maxOut + 1,\n    status_byte: maxStatus + 1\n  };\n}\n\nfunction findMappingByMac(mac) {\n  const needle = mac.trim().toLowerCase();\n  return mappings.findIndex(m => m.mac.trim().toLowerCase() === needle);\n}\n\nfunction syncFormToSelectedMapping() {\n  if (selectedMappingIdx < 0 || selectedMappingIdx >= mappings.length) {\n    return;\n  }\n  const m = mappings[selectedMappingIdx];\n  m.mac = $('map_mac').value.trim().toLowerCase();\n  m.profile = $('map_profile').value.trim() || mappingDefaults.profile;\n  m.input_byte = Number($('map_input_byte').value) || 0;\n  m.output_byte = Number($('map_output_byte').value) || 0;\n  m.status_byte = Number($('map_status_byte').value) || 0;\n  m.width = Number($('map_width').value) || mappingDefaults.width;\n  m.enabled = $('map_enabled').checked;\n  renderMappingTable();\n}\n\nfunction loadMappingIntoForm(index) {\n  if (index < 0 || index >= mappings.length) {\n    selectedMappingIdx = -1;\n    $('map_edit_label').textContent = '';\n    return;\n  }\n  selectedMappingIdx = index;\n  const m = mappings[index];\n  $('map_mac').value = m.mac;\n  $('map_profile').value = m.profile;\n  $('map_input_byte').value = m.input_byte;\n  $('map_output_byte').value = m.output_byte;\n  $('map_status_byte').value = m.status_byte;\n  $('map_width').value = m.width;\n  $('map_enabled').checked = m.enabled;\n  $('map_edit_label').textContent = `Editing mapping ${index + 1} of ${mappings.length}`;\n}\n\nfunction renderMappingTable() {\n  const tbody = $('mapping_rows');\n  if (mappings.length === 0) {\n    tbody.innerHTML = '<tr><td colspan=\"8\" class=\"muted\">No mappings - use Map on a discovered peer</td></tr>';\n    loadMappingIntoForm(-1);\n    return;\n  }\n\n  tbody.innerHTML = '';\n  mappings.forEach((m, idx) => {\n    const tr = document.createElement('tr');\n    if (idx === selectedMappingIdx) {\n      tr.className = 'selected-row';\n    }\n    tr.innerHTML = `\n      <td>${m.mac || '<span class=\"muted\">(unset)</span>'}</td>\n      <td>${m.profile}</td>\n      <td>${m.input_byte}</td>\n      <td>${m.output_byte}</td>\n      <td>${m.status_byte}</td>\n      <td>${m.width}</td>\n      <td>${m.enabled ? 'yes' : 'no'}</td>\n      <td>\n        <button class=\"button small edit-mapping\" type=\"button\" data-idx=\"${idx}\">Edit</button>\n        <button class=\"button small remove-mapping\" type=\"button\" data-idx=\"${idx}\">Remove</button>\n      </td>`;\n    tbody.appendChild(tr);\n  });\n\n  tbody.querySelectorAll('.edit-mapping').forEach(btn => {\n    btn.onclick = () => {\n      loadMappingIntoForm(Number(btn.dataset.idx));\n      $('config_preview').textContent = buildConfigText();\n    };\n  });\n  tbody.querySelectorAll('.remove-mapping').forEach(btn => {\n    btn.onclick = () => {\n      const idx = Number(btn.dataset.idx);\n      mappings.splice(idx, 1);\n      if (selectedMappingIdx === idx) {\n        loadMappingIntoForm(mappings.length > 0 ? Math.min(idx, mappings.length - 1) : -1);\n      } else if (selectedMappingIdx > idx) {\n        selectedMappingIdx -= 1;\n      }\n      renderMappingTable();\n      $('config_preview').textContent = buildConfigText();\n      showMsg('Mapping removed.');\n    };\n  });\n\n  if (selectedMappingIdx >= mappings.length) {\n    loadMappingIntoForm(mappings.length - 1);\n  }\n}\n\nfunction addOrUpdateMapping(mac, profile) {\n  const normalizedMac = mac.trim().toLowerCase();\n  const normalizedProfile = profile.trim() || mappingDefaults.profile;\n  let idx = findMappingByMac(normalizedMac);\n\n  if (idx >= 0) {\n    mappings[idx].profile = normalizedProfile;\n    mappings[idx].enabled = true;\n  } else {\n    if (mappings.length >= MAX_MAPPINGS) {\n      showMsg(`Maximum ${MAX_MAPPINGS} mappings reached.`, true);\n      return -1;\n    }\n    const bytes = nextMappingBytes();\n    mappings.push({\n      mac: normalizedMac,\n      profile: normalizedProfile,\n      input_byte: bytes.input_byte,\n      output_byte: bytes.output_byte,\n      status_byte: bytes.status_byte,\n      width: mappingDefaults.width,\n      enabled: true\n    });\n    idx = mappings.length - 1;\n  }\n\n  loadMappingIntoForm(idx);\n  renderMappingTable();\n  $('config_preview').textContent = buildConfigText();\n  return idx;\n}\n\nfunction showMsg(text, isError) {\n  const el = $('msg');\n  if (!text) {\n    el.textContent = '';\n    el.className = 'message';\n    return;\n  }\n  el.textContent = text;\n  el.className = 'message ' + (isError ? 'error' : 'success');\n}\n\nfunction setPill(id, label, value, tone) {\n  const el = $(id);\n  el.className = 'status-pill ' + (tone || 'bad');\n  el.innerHTML =\n    '<span class=\"status-pill-label\">' + label + '</span>' +\n    '<span class=\"status-pill-value\">' + value + '</span>';\n}\n\nfunction parseConfigText(text) {\n  const cfg = {\n    network: { ipv4: defaults.ipv4, mask: defaults.mask, ifname: defaults.ifname },\n    cyclic_ms: defaults.cyclic_ms,\n    mappings: []\n  };\n  let active = null;\n\n  for (const rawLine of text.split('\\n')) {\n    const line = rawLine.trim();\n    if (!line || line.startsWith('#')) continue;\n    const eq = line.indexOf('=');\n    if (eq < 0) continue;\n    const key = line.slice(0, eq).trim();\n    const value = line.slice(eq + 1).trim();\n\n    switch (key) {\n      case 'network.ipv4': cfg.network.ipv4 = value; break;\n      case 'network.mask': cfg.network.mask = value; break;\n      case 'network.ifname': cfg.network.ifname = value; break;\n      case 'cyclic_ms': cfg.cyclic_ms = Number(value) || defaults.cyclic_ms; break;\n      case 'mapping.begin': {\n        const index = Number(value);\n        if (!Number.isFinite(index) || index < 0 || index >= MAX_MAPPINGS) {\n          active = null;\n          break;\n        }\n        while (cfg.mappings.length <= index) {\n          cfg.mappings.push(defaultMapping(cfg.mappings.length));\n        }\n        active = index;\n        break;\n      }\n      case 'mapping.enabled':\n        if (active != null) cfg.mappings[active].enabled = value === '1' || value === 'true';\n        break;\n      case 'mapping.mac':\n        if (active != null) cfg.mappings[active].mac = value.toLowerCase();\n        break;\n      case 'mapping.profile':\n        if (active != null) cfg.mappings[active].profile = value;\n        break;\n      case 'mapping.input.byte':\n        if (active != null) cfg.mappings[active].input_byte = Number(value);\n        break;\n      case 'mapping.output.byte':\n        if (active != null) cfg.mappings[active].output_byte = Number(value);\n        break;\n      case 'mapping.status.byte':\n        if (active != null) cfg.mappings[active].status_byte = Number(value);\n        break;\n      case 'mapping.input.width':\n      case 'mapping.output.width':\n        if (active != null) cfg.mappings[active].width = Number(value);\n        break;\n      default: break;\n    }\n  }\n  return cfg;\n}\n\nfunction buildConfigText() {\n  if (selectedMappingIdx >= 0) {\n    syncFormToSelectedMapping();\n  }\n\n  const lines = [\n    '# LeapOS-Gateway configuration',\n    'network.mode=single',\n    `network.ifname=${$('ifname').value.trim() || 're0'}`,\n    `network.ipv4=${$('ipv4').value.trim()}`,\n    `network.mask=${$('mask').value.trim()}`,\n    'network.dhcp=0',\n    `cyclic_ms=${Number($('cyclic_ms').value) || 50}`\n  ];\n\n  mappings.forEach((m, index) => {\n    const width = Number(m.width) || mappingDefaults.width;\n    lines.push(\n      `mapping.begin=${index}`,\n      `mapping.enabled=${m.enabled ? 1 : 0}`,\n      `mapping.mac=${m.mac || '00:00:00:00:00:00'}`,\n      `mapping.profile=${m.profile || mappingDefaults.profile}`,\n      `mapping.input.byte=${Number(m.input_byte) || 0}`,\n      'mapping.input.bit=0',\n      `mapping.input.width=${width}`,\n      `mapping.output.byte=${Number(m.output_byte) || 0}`,\n      'mapping.output.bit=0',\n      `mapping.output.width=${width}`,\n      `mapping.status.byte=${Number(m.status_byte) || 0}`\n    );\n  });\n\n  return lines.join('\\n') + '\\n';\n}\n\nfunction applyConfigToForm(cfg) {\n  $('ipv4').value = cfg.network.ipv4;\n  $('mask').value = cfg.network.mask;\n  $('ifname').value = cfg.network.ifname;\n  $('cyclic_ms').value = cfg.cyclic_ms;\n  mappings = (cfg.mappings || []).map((m, index) => ({\n    mac: m.mac || '',\n    profile: m.profile || mappingDefaults.profile,\n    input_byte: Number.isFinite(m.input_byte) ? m.input_byte : index,\n    output_byte: Number.isFinite(m.output_byte) ? m.output_byte : index + 2,\n    status_byte: Number.isFinite(m.status_byte) ? m.status_byte : index + 4,\n    width: Number(m.width) || mappingDefaults.width,\n    enabled: !!m.enabled\n  }));\n  loadMappingIntoForm(mappings.length > 0 ? 0 : -1);\n  renderMappingTable();\n  $('config_preview').textContent = buildConfigText();\n  $('metricMappings').textContent = mappings.length;\n}\n\nasync function loadConfig() {\n  const r = await fetch('/api/v1/config');\n  if (!r.ok) throw new Error('Failed to load config');\n  const text = await r.text();\n  applyConfigToForm(parseConfigText(text));\n}\n\nfunction fmtBits(value, width) {\n  let out = '';\n  const w = Math.min(Math.max(width || 8, 1), 16);\n  for (let bit = w - 1; bit >= 0; bit--) {\n    const on = (value >> bit) & 1;\n    out += `<span class=\"bit ${on ? 'on' : 'off'}\">${on}</span>`;\n  }\n  return out;\n}\n\nfunction fmtHexByte(v) {\n  return '0x' + (v & 0xFF).toString(16).toUpperCase().padStart(2, '0');\n}\n\nfunction updateStatusCard(data) {\n  const phase = data.leap_phase || 'Idle';\n  const sessionTone = data.leap_session_active ? 'good'\n    : (phase !== 'Idle' && phase !== 'IDLE' ? 'warn' : 'bad');\n  setPill('pillLeap', 'LEAP', data.leap_session_active ? phase : phase, sessionTone);\n\n  const commTone = data.leap_comm_ok ? 'good' : 'bad';\n  setPill('pillComm', 'PD Comm', data.leap_comm_ok ? 'OK' : 'No data', commTone);\n\n  const storageTone = data.storage_ready ? 'good' : 'warn';\n  setPill('pillStorage', 'Storage', data.storage_ready ? 'Ready' : 'RAM only', storageTone);\n\n  $('metricMappings').textContent = data.mappings != null ? data.mappings : mappings.length;\n  $('metricOpPeers').textContent = data.leap_op_peers != null ? data.leap_op_peers : 0;\n}\n\nasync function loadIo() {\n  const r = await fetch('/api/v1/io');\n  if (!r.ok) throw new Error('I/O read failed');\n  const data = await r.json();\n  const tbody = $('io_rows');\n  const session = $('io_session');\n\n  session.textContent =\n    `Session: ${data.leap_phase}${data.session_active ? ' (owner)' : ''}` +\n    (data.leap_comm_ok ? '' : ' - no PD comm');\n\n  const rows = (data.mappings || []).filter(m => m.enabled);\n  if (rows.length === 0) {\n    tbody.innerHTML = '<tr><td colspan=\"6\" class=\"muted\">No enabled mappings</td></tr>';\n    return;\n  }\n\n  tbody.innerHTML = '';\n  rows.forEach(m => {\n    const tr = document.createElement('tr');\n    const comm = m.comm_ok\n      ? '<span class=\"io-ok\">OK</span>'\n      : '<span class=\"io-bad\">n/a</span>';\n    tr.innerHTML = `\n      <td>${m.mac}</td>\n      <td>${comm}</td>\n      <td><div>${fmtHexByte(m.leap_inputs)}</div><div class=\"bits\">${fmtBits(m.leap_inputs, m.input_width_bits)}</div></td>\n      <td><div>${fmtHexByte(m.leap_outputs)}</div><div class=\"bits\">${fmtBits(m.leap_outputs, m.output_width_bits)}</div></td>\n      <td>${fmtHexByte(m.eip_input_byte)} <span class=\"bits\">${fmtBits(m.eip_input_byte, m.input_width_bits)}</span></td>\n      <td>${fmtHexByte(m.eip_output_byte)} <span class=\"bits\">${fmtBits(m.eip_output_byte, m.output_width_bits)}</span></td>`;\n    tbody.appendChild(tr);\n  });\n}\n\nlet ioTimer = null;\nfunction startIoPoll() {\n  if (ioTimer) clearInterval(ioTimer);\n  if (!$('io_auto').checked) return;\n  ioTimer = setInterval(() => loadIo().catch(() => {}), 500);\n}\n\n$('io_refresh').onclick = () => loadIo().catch(e => showMsg(e.message, true));\n$('io_auto').onchange = startIoPoll;\n\nasync function loadStatus() {\n  const r = await fetch('/api/v1/status');\n  const data = await r.json();\n  $('stat').textContent = JSON.stringify(data, null, 2);\n  updateStatusCard(data);\n\n  if (data.storage_ready === false) {\n    showMsg('Config volume not mounted - Apply works in RAM; Save to disk needs CF/IDE boot (not read-only ISO).', true);\n  } else if (data.leap_session_active) {\n    showMsg(`LEAP owner session active (${data.leap_phase})`);\n  } else if (data.leap_phase && data.leap_phase !== 'IDLE' && data.leap_phase !== 'Idle') {\n    showMsg(`LEAP session state: ${data.leap_phase}`);\n  }\n}\n\nasync function loadPeers() {\n  const r = await fetch('/api/v1/leap/peers');\n  const data = await r.json();\n  const tbody = $('peers');\n  tbody.innerHTML = '';\n  (data.peers || []).forEach(p => {\n    const tr = document.createElement('tr');\n    const stateLabel = LEAP_STATES[p.state] ? `${LEAP_STATES[p.state]} (${p.state})` : p.state;\n    tr.innerHTML = `\n      <td>${p.mac}</td>\n      <td>${p.profile}</td>\n      <td>${stateLabel}</td>\n      <td>${p.owner}</td>\n      <td><button class=\"button small primary map-peer\" type=\"button\" data-mac=\"${p.mac}\" data-profile=\"${p.profile}\">Map</button></td>`;\n    tbody.appendChild(tr);\n  });\n  tbody.querySelectorAll('.map-peer').forEach(btn => {\n    btn.onclick = () => {\n      const idx = addOrUpdateMapping(btn.dataset.mac, btn.dataset.profile);\n      if (idx >= 0) {\n        showMsg(`Mapped peer ${btn.dataset.mac} (slot ${idx + 1})`);\n      }\n    };\n  });\n}\n\nasync function applyConfig() {\n  const body = buildConfigText();\n  $('config_preview').textContent = body;\n  const r = await fetch('/api/v1/config', { method: 'PUT', body });\n  const text = await r.text();\n  if (!r.ok) throw new Error(text || 'Apply failed');\n  showMsg('Configuration applied. Click Connect LEAP when ready. IP changes still need reboot.');\n}\n\nasync function connectLeap() {\n  const r = await fetch('/api/v1/leap/connect', { method: 'POST' });\n  const text = await r.text();\n  if (!r.ok) throw new Error(text || 'Connect failed');\n  showMsg('LEAP connect requested.');\n  await loadStatus();\n}\n\nasync function persistConfig() {\n  await applyConfig();\n  const r = await fetch('/api/v1/config/apply', { method: 'POST' });\n  const text = await r.text();\n  if (!r.ok) throw new Error(text || 'Save failed');\n  showMsg('Configuration saved to disk.');\n}\n\nfunction wirePreviewUpdates() {\n  ['ipv4','mask','ifname','cyclic_ms'].forEach(id => {\n    $(id).addEventListener('input', () => {\n      $('config_preview').textContent = buildConfigText();\n    });\n    $(id).addEventListener('change', () => {\n      $('config_preview').textContent = buildConfigText();\n    });\n  });\n\n  ['map_mac','map_profile','map_input_byte','map_output_byte',\n   'map_status_byte','map_width','map_enabled'].forEach(id => {\n    $(id).addEventListener('input', () => {\n      syncFormToSelectedMapping();\n      $('config_preview').textContent = buildConfigText();\n    });\n    $(id).addEventListener('change', () => {\n      syncFormToSelectedMapping();\n      $('config_preview').textContent = buildConfigText();\n    });\n  });\n}\n\n$('map_add').onclick = () => {\n  if (mappings.length >= MAX_MAPPINGS) {\n    showMsg(`Maximum ${MAX_MAPPINGS} mappings reached.`, true);\n    return;\n  }\n  const bytes = nextMappingBytes();\n  mappings.push({\n    mac: '',\n    profile: mappingDefaults.profile,\n    input_byte: bytes.input_byte,\n    output_byte: bytes.output_byte,\n    status_byte: bytes.status_byte,\n    width: mappingDefaults.width,\n    enabled: false\n  });\n  loadMappingIntoForm(mappings.length - 1);\n  renderMappingTable();\n  $('config_preview').textContent = buildConfigText();\n  $('metricMappings').textContent = mappings.length;\n  showMsg('Added empty mapping - set MAC and byte offsets, then Apply.');\n};\n\n$('scan').onclick = async () => {\n  showMsg('Scanning LEAP network...');\n  await fetch('/api/v1/leap/discover?scan_ms=1000', { method: 'POST' });\n  await new Promise(r => setTimeout(r, 1200));\n  await loadPeers();\n  showMsg('Scan complete.');\n};\n\n$('connect_leap').onclick = async () => {\n  try {\n    await connectLeap();\n  } catch (e) {\n    showMsg(e.message, true);\n  }\n};\n\n$('reload').onclick = async () => {\n  try {\n    await loadConfig();\n    showMsg('Configuration loaded.');\n  } catch (e) {\n    showMsg(e.message, true);\n  }\n};\n\n$('status').onclick = () => loadStatus().catch(e => showMsg(e.message, true));\n\n$('save').onclick = async () => {\n  try {\n    await applyConfig();\n  } catch (e) {\n    showMsg(e.message, true);\n  }\n};\n\n$('persist').onclick = async () => {\n  try {\n    await persistConfig();\n  } catch (e) {\n    showMsg(e.message, true);\n  }\n};\n\nwirePreviewUpdates();\nloadConfig().catch(() => applyConfigToForm({\n  network: defaults,\n  cyclic_ms: defaults.cyclic_ms,\n  mappings: []\n}));\nloadStatus();\nloadPeers();\nloadIo().catch(() => {});\nstartIoPoll();\n</script>\n</body>\n</html>\n";

const size_t leap_gateway_web_index_html_len = sizeof(leap_gateway_web_index_html) - 1u;
